      -3.13439595459041875e-14_dp, 1.12305275033290162e-17_dp, -1.37784026086699514e-19_dp, &
      1.12567798961278980e-05_dp, -2.05308601156084717e-08_dp, 1.20360691617941661e-11_dp, &
      -5.74938351322138580e-15_dp, 2.43126690293559315e-18_dp, -8.89384594617015356e-21_dp, &
      1.31397615128105425e-06_dp, -3.08123495233655201e-09_dp, 2.20776310836927980e-12_dp, &
      -1.24634880725240836e-15_dp, 6.09193154273186525e-19_dp, -7.23507309113048175e-22_dp, &
      1.97199276248565325e-07_dp, -5.65187667688473093e-10_dp, 4.78598009024793986e-13_dp, &
      -3.11749417445761172e-16_dp, 1.72556493223461997e-19_dp, -1.89700087145494331e-22_dp, &
      3.61720705879644697e-08_dp, -1.22521178709642747e-10_dp, 1.19711801510153671e-13_dp, &
      -8.83747987399732013e-17_dp, 5.46898733795559778e-20_dp, -4.74250217863735828e-23_dp, &
      7.84137240538679053e-09_dp, -3.06462491871789705e-11_dp, 3.39359366193552999e-14_dp, &
      -2.79996904007368525e-17_dp, 1.91489554537317377e-20_dp, -1.64057488156350479e-23_dp, &
      1.96136532392386323e-09_dp, -8.68760957964770020e-12_dp, 1.07518882863544079e-14_dp, &
      -9.80475074733021831e-18_dp, 7.34508811260003424e-21_dp, -6.99656934784435810e-24_dp &
      /)
   !$acc declare create(boys_table)



contains

   !
   ! Push the table to the device.  `declare create` allocates device storage
   ! but does NOT carry the host initialiser across -- a device copy full of
   ! garbage is exactly the silent-wrong-answer failure the whole project is
   ! trying to avoid, so the transfer is explicit and must be called once
   ! before any kernel.
   !
   subroutine boys_init()
      !$acc update device(boys_table)
   end subroutine boys_init

   !
   ! F_0..F_m(t) into f(0:m), for any m <= BOYS_MMAX.
   !
   ! Pure and side-effect free so it can be called from a device kernel.
   ! Marked `!$acc routine seq` because stdpar only auto-inlines within a
   ! translation unit and this is called across a module boundary.
   !
   pure subroutine boys_eval(m, t, f)
      !$acc routine seq
      integer,  intent(in)  :: m
      real(dp), intent(in)  :: t
      real(dp), intent(out) :: f(0:)
      integer  :: i, k, j, jj, base
      real(dp) :: x, x2, b0, b1, b2, et, tt

      if (t >= BOYS_TMAX) then
         ! Large T.  Needs erf regardless, and is rare enough not to matter.
         tt = sqrt(t)
         f(0) = 0.88622692545275801365_dp*erf(tt)/tt
         et = exp(-t)
         do k = 1, m
            f(k) = (real(2*k - 1, dp)*f(k - 1) - et)*(0.5_dp/t)
         end do
         return
      end if

      !
      ! Degree-5 Chebyshev, evaluated per order by Clenshaw recurrence.
      !
      ! Direct per order -- no downward recurrence, so no division and no
      ! exp(-T).  This is the structure used in [1] -- one interpolator per
      ! order, at a degree that keeps the whole table inside L2.
      !
      i = int(t*BOYS_DTINV)
      if (i >= BOYS_NGRID) i = BOYS_NGRID - 1
      ! map the interval onto [-1, 1]
      x = 2.0_dp*(t - real(i, dp)*BOYS_DT)*BOYS_DTINV - 1.0_dp
      x2 = 2.0_dp*x
      base = i*(BOYS_MMAX + 1)*(BOYS_NCHEB + 1)

      do k = 0, m
         j = base + k*(BOYS_NCHEB + 1)
         b1 = 0.0_dp; b2 = 0.0_dp
         do jj = BOYS_NCHEB, 1, -1
            b0 = x2*b1 - b2 + boys_table(j + jj + 1)
            b2 = b1; b1 = b0
         end do
         f(k) = x*b1 - b2 + boys_table(j + 1)
      end do
   end subroutine boys_eval

end module trc_boys
